@startuml

class Gym {
  + computeOverallBalanceMonth(m : date) : int
  + computeOverallBalanceYear(y : int) : int
  + sendArrearsReminders()
  + sendMedicalCheckReminders()
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

abstract class Subscription {
  + startDate : date
}

class MonthlySubscription extends Subscription {}

class AnnualSubscription extends Subscription {}

abstract class Service {
  + name : string
  + additionalCost : float
}

class BaseService extends Service {}

class AdditionalService extends Service {}

class WorkoutPlan {
  + visitsPerWeek : int
}

class WorkoutPlanExercise {
  + exerciseName : string
  + repetitions : int
  + frequency : string
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
  + date : date
}

class MedicalStaff {
  + name : string
}

Customer "1" -- "1" Subscription : has
Customer "1" -- "0..1" WorkoutPlan : associatedWith
Customer "0..1" -- "0..*" MedicalCheck : undergoes
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Customer : assists
Gym "1" -- "*" Subscription : offers
Gym "1" -- "*" Service : offers
Gym "1" -- "*" MedicalStaff : employs
Subscription "1" -- "1..*" BaseService : includes
Subscription "1" -- "0..*" AdditionalService : includes
WorkoutPlan "1" -- "1..*" WorkoutPlanExercise : defines
WorkoutPlan "1" -- "0..*" AdditionalService : takesIntoAccount

@enduml

